import pptx

pptx_path = "/Data2-v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx".replace("-","/")

from pptx import Presentation

def extract_slide_texts(p):
    prs = Presentation(p)
    out = []
    for i, slide in enumerate(prs.slides, start=1):
        parts = []
        for shape in slide.shapes:
            if hasattr(shape, "text"):
                t = shape.text
                if t:
                    parts.append(t)
        if slide.has_notes_slide and slide.notes_slide and slide.notes_slide.notes_text_frame:
            nt = slide.notes_slide.notes_text_frame.text
            if nt:
                parts.append(nt)
        out.append({"slide": i, "text": " ".join(parts)})
    return out

slides = extract_slide_texts(pptx_path)
for s in slides:
    print(f"Slide {s['slide']}: {s['text']}")

